  Lemma alloc_sec_t1c : forall (x1 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x28 x29 x30 x31 : word) (mX : mem) (j8 : list byte) (ob0 : byte) (hb1 nd8 : Z),
